import React from 'react';
import { Link } from 'react-router-dom';
import './DashboardWorker.css';

function DashboardWorker() {
  const tasks = [
    { title: 'Desain Logo Cafe Kopi Minimalis', price: 'Rp 300k', level: 'Menengah', type: 'Solo Project', slots: '1/1', category: 'Desain' },
    { title: 'Edit Video Reels TikTok F&B', price: 'Rp 500k', level: 'Mahir', type: 'Team Project', slots: '2/5', category: 'Editing' },
    { title: 'Copywriting Landing Page Fintech', price: 'Rp 250k', level: 'Pemula', type: 'Solo Project', slots: '1/1', category: 'Tulisan' }
  ];

  return (
    <div className="dashboard-worker">
      <header className="dashboard-header">
        <div className="header-top"><h1>WORKIE</h1><div className="header-icons"><span>🔔</span><span>👤</span></div></div>
        <h2>Halo Mitra, Cari Duit Instan!</h2>
      </header>
      <div className="categories-section">
        <div className="category-chips"><span className="chip active">Desain</span><span className="chip">Editing</span><span className="chip">Tulisan</span></div>
      </div>
      <div className="tasks-section">
        <h3>Tugas Tersedia Hari Ini</h3>
        {tasks.map((task, i) => (
          <div key={i} className="task-card">
            <div className="task-header"><span className="category-tag">{task.category}</span><span className="level-tag">{task.level}</span></div>
            <h4>{task.title}</h4>
            <p className="price">{task.price}</p>
            <div className="task-meta"><span>{task.type}</span><span>{task.slots}</span></div>
            <button className="btn-take">Ambil Pekerjaan (Mulai)</button>
          </div>
        ))}
      </div>
      <div className="bottom-nav">
        <Link to="/dashboard-worker" className="nav-item active">🏠 Home</Link>
        <Link to="/" className="nav-item">📋 Orders</Link>
        <Link to="/" className="nav-item">💬 Chat</Link>
        <Link to="/" className="nav-item">💳 Wallet</Link>
        <Link to="/" className="nav-item">👤 Profile</Link>
      </div>
    </div>
  );
}

export default DashboardWorker;
